// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Restrict to admissible domain: caller must be the authorized from address, and arrays non-empty
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // For each element, bound the value to a reasonable range to prevent overflow in mul_uint256
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000 - 1);
            // ensure _tos[i] is a non-zero address to avoid obvious issues
            vm.assume(_tos[i] != address(0));
        }
        // The caller must be the authorized from address; that is hardcoded in the contract.
        // We prank the caller to be that specific address.
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Wrap the call in try/catch to detect only non-reverting executions
        bool ok;
        bool result;
        try c.transfer(_tos, v) returns (bool returnValue) {
            ok = true;
            result = returnValue;
        } catch {
            ok = false;
        }
        // Assert that if the call does not revert, the return value must be true.
        // The reference contract always returns true when it doesn't revert;
        // the buggy mutant returns false without reverting for the same inputs.
        assertTrue(!ok || result);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    function test(address sender, address[] memory _tos, uint[] memory v) public returns (bool) {
        require(_tos.length > 0);
        require(v.length == _tos.length);
        vm.prank(sender);
        bool ok = c.transfer(_tos, v);
        assert(sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9 || !ok);
        return ok;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(true);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9 || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory _tos, uint[] memory v) public payable {
        require(caller != address(0));
        bool reverted;
        vm.prank(caller);
        try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

